const D={up:[1,0],down:[-1,0],left:[0,-1],right:[0,1]};
const GR=2,GC=2;
function dist(s){return Math.abs(GR-s.r)+Math.abs(GC-s.c);}
export function initialState(){return {r:0,c:0,moves:0,hint:false,msg:'Reach the green goal square.'};}
export function reduce({state,event}){
if(event.type!=='action')return state;
const a=event.action;
if(dist(state)===0)return state;
if(a==='hint')return {...state,hint:true,msg:'Follow the orange arrow: it moves one step closer.'};
const d=D[a];if(!d)return state;
const r=state.r+d[0],c=state.c+d[1];
if(r<0||r>2||c<0||c>2)return {...state,hint:false,msg:'That move would leave the board.'};
return {...state,r,c,moves:state.moves+1,hint:false,msg:'Keep going.'};
}
function pos(r,c,y){return [(c-1)*1.1,y,(1-r)*1.1];}
export function evaluate({state}){
const s=state||initialState();
const k=dist(s);
const y=k===0?0.46:0.4;
const p=pos(s.r,s.c,y);
const S=Math.SQRT1_2;
const q=s.c<GC?[0,0,-S,S]:[-S,0,0,S];
const won=k===0;
let message=s.msg;
if(won)message='You reached the goal in '+s.moves+' moves. The shortest route is 4 moves'+(s.moves===4?' - perfect!':'.');
return {nodes:{tokenN:{position:p},hintN:{position:p,quaternion:q,visible:s.hint&&!won}},readouts:{moves:s.moves,steps:k},goal:{status:won?'won':'playing',message}};
}
